const now = new Date();
const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

const sanitizeEmailContent = (rawHtml) => {
  if (!rawHtml || typeof rawHtml !== 'string') return '';

  return rawHtml
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<(br|p|div|tr)[^>]*>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#039;/gi, "'")
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s*\n+/g, '\n')
    .trim();
};

const validIncidentEmails = [];

const safetyTermsRegex = /incident|inc-|injury|damage|spill|leak|near miss|hazard|danger|collision|crash|accident|crane|reach stacker|forklift|fire|first aid|safety|hse|fatality|broken|wound|hurt|equipment|fall|سقوط|إصابة|اصطدام|تلف|عطل|تسريب|حريق|حادث|خطر|رافعة|سلامة/i;
const systemIgnoredSendersRegex = /no-?reply|welcome|marketing|newsletter|accountprotection|microsoft/i;

for (const item of $input.all()) {
  const data = item.json;

  if (!data || Object.keys(data).length === 0) continue;

  const senderAddress = data.from?.emailAddress?.address || data.sender?.emailAddress?.address || '';
  if (systemIgnoredSendersRegex.test(senderAddress)) {
    continue;
  }

  const receivedDateStr = data.receivedDateTime || data.sentDateTime;
  if (receivedDateStr) {
    const emailDate = new Date(receivedDateStr);
    if (!isNaN(emailDate.getTime()) && emailDate < sevenDaysAgo) {
      continue;
    }
  }

  const subject = (data.subject || '').trim();
  const rawBody = data.body?.content || data.bodyPreview || data.body || '';

  const fullTextToInspect = `${subject}\n${rawBody}`;
  if (!safetyTermsRegex.test(fullTextToInspect)) {
    continue;
  }

  const cleanedBody = sanitizeEmailContent(rawBody).slice(0, 6000);

  validIncidentEmails.push({
    id: data.id || `msg-${validIncidentEmails.length + 1}`,
    sender: senderAddress || 'Unknown Sender',
    subject: subject || 'HSE Notification',
    received: receivedDateStr || now.toISOString(),
    hasAttachments: Boolean(data.hasAttachments),
    body: cleanedBody
  });
}

return [{
  json: {
    count: validIncidentEmails.length,
    periodFrom: sevenDaysAgo.toISOString().split('T')[0],
    periodTo: now.toISOString().split('T')[0],
    emails: validIncidentEmails
  }
}];

