const escapeHtml = (str) => {
  if (str === null || str === undefined) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
};

const data = $input.first().json.output || $input.first().json;

const period = escapeHtml(data.period || 'Not specified');
const total = escapeHtml(data.total_incidents ?? 0);
const trends = escapeHtml(data.trends_and_patterns || 'No patterns observed.');

let riskAlertsHtml = '';
if (Array.isArray(data.risk_alerts) && data.risk_alerts.length > 0) {
  const alertsList = data.risk_alerts.map(a => `<li style="margin-bottom: 6px;">${escapeHtml(a)}</li>`).join('');
  riskAlertsHtml = `
    <div style="background-color: #fee2e2; border-left: 5px solid #dc2626; padding: 14px 18px; margin: 20px 0; border-radius: 4px;">
      <h3 style="margin: 0 0 8px 0; color: #991b1b; font-size: 16px;">⚠️ Immediate Risk Alerts</h3>
      <ul style="margin: 0; padding-left: 20px; color: #7f1d1d; font-size: 14px;">
        ${alertsList}
      </ul>
    </div>
  `;
}

let incidentsRows = '';
if (Array.isArray(data.incidents) && data.incidents.length > 0) {
  incidentsRows = data.incidents.map(inc => {
    let sevColor = '#4b5563';
    const s = String(inc.severity || '').toLowerCase();
    if (s === 'critical') sevColor = '#dc2626';
    else if (s === 'high') sevColor = '#ea580c';
    else if (s === 'medium') sevColor = '#d97706';
    else if (s === 'low') sevColor = '#16a34a';

    return `
      <tr style="border-bottom: 1px solid #e5e7eb; font-size: 13px;">
        <td style="padding: 10px 12px; white-space: nowrap;">${escapeHtml(inc.date || 'Not specified')}</td>
        <td style="padding: 10px 12px;">${escapeHtml(inc.type || 'Not specified')}</td>
        <td style="padding: 10px 12px;"><span style="font-weight: 600; color: ${sevColor};">${escapeHtml(inc.severity || 'Not specified')}</span></td>
        <td style="padding: 10px 12px;">${escapeHtml(inc.location || 'Not specified')}</td>
        <td style="padding: 10px 12px;">${escapeHtml(inc.injuries || 'Not specified')}</td>
        <td style="padding: 10px 12px;">${escapeHtml(inc.root_cause || 'Not specified')}</td>
        <td style="padding: 10px 12px;">${escapeHtml(inc.corrective_actions || 'Not specified')}</td>
        <td style="padding: 10px 12px;"><span style="padding: 3px 8px; border-radius: 9999px; background: #e0f2fe; color: #0369a1; font-size: 11px;">${escapeHtml(inc.status || 'Not specified')}</span></td>
      </tr>
    `;
  }).join('');
} else {
  incidentsRows = `<tr><td colspan="8" style="padding: 12px; text-align: center; color: #6b7280;">No incidents to display</td></tr>`;
}

const makeBreakdownTable = (title, obj) => {
  if (!obj || Object.keys(obj).length === 0) return '';
  const rows = Object.entries(obj).map(([k, v]) => `
    <tr style="border-bottom: 1px solid #f3f4f6;">
      <td style="padding: 6px 10px; font-size: 13px; color: #374151;">${escapeHtml(k)}</td>
      <td style="padding: 6px 10px; font-size: 13px; font-weight: bold; text-align: right; color: #111827;">${escapeHtml(v)}</td>
    </tr>
  `).join('');
  return `
    <div style="flex: 1; min-width: 200px; margin: 8px; background: #f9fafb; border: 1px solid #e5e7eb; border-radius: 6px; padding: 12px;">
      <h4 style="margin: 0 0 8px 0; color: #1f2937; font-size: 14px; border-bottom: 2px solid #3b82f6; padding-bottom: 4px;">${title}</h4>
      <table style="width: 100%; border-collapse: collapse;">
        ${rows}
      </table>
    </div>
  `;
};

const severityTable = makeBreakdownTable('By Severity', data.by_severity);
const typeTable = makeBreakdownTable('By Incident Type', data.by_type);
const locationTable = makeBreakdownTable('By Location', data.by_location);

let recsHtml = '';
if (Array.isArray(data.recommendations) && data.recommendations.length > 0) {
  const listItems = data.recommendations.map(r => `<li style="margin-bottom: 8px; color: #1f2937;">${escapeHtml(r)}</li>`).join('');
  recsHtml = `
    <div style="margin-top: 24px; padding: 16px; background: #f0fdf4; border-left: 5px solid #16a34a; border-radius: 4px;">
      <h3 style="margin: 0 0 10px 0; color: #166534; font-size: 16px;">💡 HSE Actionable Recommendations</h3>
      <ol style="margin: 0; padding-left: 20px; font-size: 14px; line-height: 1.5;">
        ${listItems}
      </ol>
    </div>
  `;
}

const htmlEmail = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <title>HSE Incident Analysis</title>
</head>
<body style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; background-color: #f3f4f6; margin: 0; padding: 20px;">
  <div style="max-width: 900px; margin: 0 auto; background: #ffffff; border-radius: 8px; overflow: hidden; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);">
    <div style="background: linear-gradient(135deg, #1e3a8a 0%, #2563eb 100%); color: #ffffff; padding: 24px 30px;">
      <h1 style="margin: 0; font-size: 22px; font-weight: 700;">HSE Incident Weekly Analysis Report</h1>
      <p style="margin: 6px 0 0 0; font-size: 14px; opacity: 0.9;">Coverage Period: <strong>${period}</strong> | Total Incidents Reported: <strong>${total}</strong></p>
    </div>
    <div style="padding: 24px 30px;">
      ${riskAlertsHtml}
      <h3 style="margin: 20px 0 12px 0; color: #111827; font-size: 16px;">Incident Registry</h3>
      <div style="overflow-x: auto;">
        <table style="width: 100%; border-collapse: collapse; text-align: left;">
          <thead>
            <tr style="background: #f8fafc; border-bottom: 2px solid #cbd5e1; color: #475569; font-size: 12px; text-transform: uppercase;">
              <th style="padding: 10px 12px;">Date</th>
              <th style="padding: 10px 12px;">Type</th>
              <th style="padding: 10px 12px;">Severity</th>
              <th style="padding: 10px 12px;">Location</th>
              <th style="padding: 10px 12px;">Injuries</th>
              <th style="padding: 10px 12px;">Root Cause</th>
              <th style="padding: 10px 12px;">Corrective Actions</th>
              <th style="padding: 10px 12px;">Status</th>
            </tr>
          </thead>
          <tbody>
            ${incidentsRows}
          </tbody>
        </table>
      </div>
      <h3 style="margin: 28px 0 12px 0; color: #111827; font-size: 16px;">Incident Distributions</h3>
      <div style="display: flex; flex-wrap: wrap; margin: -8px;">
        ${severityTable}
        ${typeTable}
        ${locationTable}
      </div>
      <div style="margin-top: 24px; padding: 16px; background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 6px;">
        <h3 style="margin: 0 0 8px 0; color: #0f172a; font-size: 15px;">🔍 Trends & Patterns Identified</h3>
        <p style="margin: 0; color: #334155; font-size: 14px; line-height: 1.6;">${trends}</p>
      </div>
      ${recsHtml}
      <div style="margin-top: 30px; padding-top: 16px; border-top: 1px solid #e5e7eb; text-align: center; color: #9ca3af; font-size: 12px;">
        Autonomous HSE Intelligence System • Powered by n8n Agentic Workflow
      </div>
    </div>
  </div>
</body>
</html>
`;

return [{
  json: {
    htmlEmail: htmlEmail
  }
}];
